import math

def prime_fib(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        max_divisor = math.isqrt(num) + 1
        for d in range(3, max_divisor, 2):
            if num % d == 0:
                return False
        return True

    fib = [0, 1]
    count = 0
    while count < n:
        next_fib = fib[-1] + fib[-2]
        fib.append(next_fib)
        if is_prime(next_fib):
            count += 1
    return fib[-1]
