def search(lst):
    freq = defaultdict(int)
    for num in lst:
        freq[num] += 1

    max_num = -1
    for num in sorted(freq.keys(), reverse=True):
        if freq[num] >= num and num > 0:
            max_num = num
            break
    return max_num
