def is_simple_power(x, n):
    """Returns True if x is a simple power of n (i.e., n^int = x for some integer int),
    otherwise returns False."""
    if n == 0:
        return False
    if x == 1:
        return n == 1
    if x < 1 or n < 1:
        return False
    if x % n != 0:
        return False
    current = n
    while current < x:
        current *= n
    return current == x
