def is_simple_power(x, n):
    """Check if x is a simple power of n (n raised to an integer power equals x)."""
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1
    if x <= 0 or n <= 0:
        return False

    # Handle case where n is negative (though x must be positive)
    if n < 0 and x < 0:
        return abs(x) == abs(n) ** int(abs(x).bit_length() - 1)
    if n < 0:
        return abs(x) == abs(n) ** int(abs(x).bit_length() - 1)

    # Check if x can be represented as n^k for some integer k >= 1
    k = 1
    while n ** k <= x:
        if n ** k == x:
            return True
        k += 1
    return False
