def decimal_to_binary(decimal):
    """Convert a decimal number to binary string with 'db' prefixes and suffixes."""
    binary_digits = []
    if decimal == 0:
        binary_digits.append('0')
    else:
        while decimal > 0:
            binary_digits.append(str(decimal % 2))
            decimal = decimal // 2
    binary_str = ''.join(reversed(binary_digits))
    return f"db{binary_str}db"
