    the factorial of i is the multiplication of the numbers from 1 to i (1 * 2 * ... * i).
    Example:
    f(5) == [1, 2, 6, 24, 15]
    """
    result = []
    factorial_cache = {}
    def factorial(i):
        if i in factorial_cache:
            return factorial_cache[i]
        if i == 1:
            return 1
        result[i] = factorial(i - 1) * i
        return result[i]

    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            sum_val = i * (i + 1) // 2
            result.append(sum_val)
    return result

