    total_wells = len(grid)
    total_units = 0
    total_units_per_well = len(grid[0]) if total_wells > 0 else 0

    for well in grid:
        total_units += sum(well)

    if total_units == 0:
        return 0

    max_possible_per_well = math.ceil(total_units / total_wells)

    if max_possible_per_well <= capacity:
        return total_wells

    result = 0
    for well in grid:
        well_units = sum(well)
        if well_units <= capacity:
            result += 1
        else:
            result += math.ceil(well_units / capacity)

    return result
