    Sorts an array of non-negative integers based on the number of ones in their binary representation in ascending order.
    For numbers with the same number of ones, sorts by their decimal value in ascending order.
    Handles negative numbers correctly by treating their binary representation as if they were positive (absolute value).
    """
    def count_ones(x):
        return bin(abs(x)).count('1')

    return sorted(arr, key=lambda x: (count_ones(x), x))
