def get_closest_vowel(word):
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    closest_vowel = None
    min_distance = float('inf')

    for i in range(1, len(word) - 1):
        current_char = word[i]
        if current_char in vowels:
            # Check left consonant
            left_consonant = word[i - 1] not in vowels and word[i - 1] != ''
            # Check right consonant
            right_consonant = word[i + 1] not in vowels and word[i + 1] != ''
            if left_consonant and right_consonant:
                distance = min(i - 1, len(word) - i - 1)
                if distance < min_distance:
                    min_distance = distance
                    closest_vowel = current_char
    return closest_vowel
