        return 'No'

    # Check all possible concatenations
    def is_good(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    if is_good(s1 + s2) or is_good(s2 + s1):
        return 'Yes'
    else:
        return 'No'
