        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    filtered_words = [word for word in words if is_prime(len(word))]
    return ' '.join(filtered_words)
